"""LedgerLock core: an append-only, tamper-evident key/value ledger.

The on-disk format is a single JSONL file. Each line is a JSON object
carrying ``op``, ``key``, ``ts``, ``id`` and (for ``put``) ``value``,
plus a ``hash`` and ``prev_hash`` field that form a SHA-256 hash chain.

The first line's ``prev_hash`` is the literal string ``"GENESIS"``.
"""

from __future__ import annotations

import hashlib
import json
import os
import tempfile
import unicodedata

GENESIS = "GENESIS"


def normalize_key(key):
    """Return ``key`` normalized to Unicode NFC form."""
    return unicodedata.normalize("NFC", key)


def canonical_bytes(line):
    """Serialize a line dict deterministically to UTF-8 bytes."""
    return json.dumps(
        line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def line_hash(prev_hash, line):
    """SHA-256 of ``prev_hash + "|" + canonical(line_without_hash_fields)``."""
    stripped = dict(line)
    stripped["hash"] = ""
    stripped["prev_hash"] = ""
    payload = json.dumps(
        stripped, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    )
    return hashlib.sha256((prev_hash + "|" + payload).encode("utf-8")).hexdigest()


class ConflictError(Exception):
    """Raised when a different rid targets a key with a committed mutation."""

    def __init__(self, key, incoming_rid, committed_rid, batch_index=None):
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index
        if batch_index is None:
            message = (
                f"conflict on key {key!r}: rid {incoming_rid!r} != "
                f"committed {committed_rid!r}"
            )
        else:
            message = (
                f"conflict on key {key!r} (batch element {batch_index}): "
                f"rid {incoming_rid!r} != committed {committed_rid!r}"
            )
        super().__init__(message)


def _split_lines(raw):
    """Split raw JSONL bytes into line bytes, dropping the trailing newline."""
    if not raw:
        return []
    parts = raw.split(b"\n")
    if parts[-1] == b"":
        parts = parts[:-1]
    return parts


class Ledger:
    """An append-only ledger stored at ``path`` (created on first mutation)."""

    def __init__(self, path):
        self.path = os.fspath(path)

    # -- file I/O -----------------------------------------------------------

    def _read_bytes(self):
        with open(self.path, "rb") as handle:
            return handle.read()

    def _append_bytes(self, data):
        with open(self.path, "ab") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())

    def _write_atomic(self, data):
        directory = os.path.dirname(self.path) or "."
        fd, tmp_path = tempfile.mkstemp(
            dir=directory, prefix=".ledgerlock.", suffix=".tmp"
        )
        try:
            with os.fdopen(fd, "wb") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp_path, self.path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    # -- helpers ------------------------------------------------------------

    @staticmethod
    def _coerce_op(op):
        if not isinstance(op, (list, tuple)):
            raise TypeError(f"op must be a tuple or list, got {type(op).__name__}")
        items = list(op)
        if not items:
            raise ValueError("op must not be empty")
        name = items[0]
        if name == "put":
            if len(items) != 5:
                raise ValueError(f"put op needs 5 fields, got {len(items)}")
            _, key, value, rid, ts = items
            return "put", key, value, rid, ts
        if name == "delete":
            if len(items) != 4:
                raise ValueError(f"delete op needs 4 fields, got {len(items)}")
            _, key, rid, ts = items
            return "delete", key, None, rid, ts
        raise ValueError(f"unknown op {name!r}")

    @staticmethod
    def _build_line(name, key, value, rid, ts, prev_hash):
        line = {"op": name, "key": key, "ts": ts, "id": rid}
        if name == "put":
            line["value"] = value
        line["prev_hash"] = prev_hash
        line["hash"] = line_hash(prev_hash, line)
        return line

    def _committed_lines(self, raw):
        lines = []
        tail = GENESIS
        for line_bytes in _split_lines(raw):
            if line_bytes == b"":
                continue
            try:
                obj = json.loads(line_bytes)
            except (ValueError, UnicodeDecodeError):
                break
            if not isinstance(obj, dict):
                break
            lines.append(obj)
            tail = obj.get("hash", tail)
        return lines, tail

    # -- mutations ----------------------------------------------------------

    def append(self, op):
        """Commit one mutation. ``op`` is ``(put, key, value, rid, ts)`` or
        ``(delete, key, rid, ts)``. Returns the committed line dict."""
        name, key, value, rid, ts = self._coerce_op(op)
        key = normalize_key(key)
        if not key:
            raise ValueError("empty key after NFC normalization")
        if not isinstance(rid, str) or not rid:
            raise ValueError("rid must be a non-empty string")
        try:
            raw = self._read_bytes()
        except FileNotFoundError:
            raw = b""
        lines, tail = self._committed_lines(raw)
        last_line = None
        for line in lines:
            if line.get("key") == key:
                last_line = line
        if last_line is not None:
            if last_line.get("id") == rid:
                return dict(last_line)
            raise ConflictError(
                key=key,
                incoming_rid=rid,
                committed_rid=last_line.get("id"),
            )
        new_line = self._build_line(name, key, value, rid, ts, tail)
        self._append_bytes(canonical_bytes(new_line) + b"\n")
        return new_line

    def apply_batch(self, ops):
        """Commit a batch atomically. Returns the number of lines appended."""
        normalized = []
        for op in ops:
            normalized.append(self._coerce_op(op))
        try:
            raw = self._read_bytes()
        except FileNotFoundError:
            raw = b""
        lines, tail = self._committed_lines(raw)
        last_by_key = {}
        for line in lines:
            last_by_key[line.get("key")] = line

        new_lines = []
        for index, (name, key, value, rid, ts) in enumerate(normalized):
            key = normalize_key(key)
            if not key:
                raise ValueError(
                    f"empty key after NFC normalization (batch element {index})"
                )
            if not isinstance(rid, str) or not rid:
                raise ValueError(
                    f"rid must be a non-empty string (batch element {index})"
                )
            committed = last_by_key.get(key)
            if committed is not None:
                if committed.get("id") == rid:
                    continue
                raise ConflictError(
                    key=key,
                    incoming_rid=rid,
                    committed_rid=committed.get("id"),
                    batch_index=index,
                )
            line = self._build_line(name, key, value, rid, ts, tail)
            new_lines.append(line)
            last_by_key[key] = line
            tail = line["hash"]

        if not new_lines:
            return 0
        appended = b"".join(canonical_bytes(line) + b"\n" for line in new_lines)
        self._write_atomic(raw + appended)
        return len(new_lines)

    # -- reads --------------------------------------------------------------

    def verify(self):
        """Recompute the chain end-to-end from disk, ignoring in-memory state."""
        raw = self._read_bytes()
        if not raw:
            return {"ok": True, "first_bad_index": None}
        prev = GENESIS
        for index, line_bytes in enumerate(_split_lines(raw)):
            if line_bytes == b"":
                return {"ok": False, "first_bad_index": index}
            try:
                obj = json.loads(line_bytes)
            except (ValueError, UnicodeDecodeError):
                return {"ok": False, "first_bad_index": index}
            if not isinstance(obj, dict):
                return {"ok": False, "first_bad_index": index}
            if obj.get("prev_hash") != prev:
                return {"ok": False, "first_bad_index": index}
            if obj.get("hash") != line_hash(prev, obj):
                return {"ok": False, "first_bad_index": index}
            prev = obj.get("hash")
        return {"ok": True, "first_bad_index": None}

    def snapshot(self):
        """Materialize the current state as a dict, NFC-sorted by key."""
        try:
            raw = self._read_bytes()
        except FileNotFoundError:
            return {}
        state = {}
        for line_bytes in _split_lines(raw):
            if line_bytes == b"":
                continue
            try:
                obj = json.loads(line_bytes)
            except (ValueError, UnicodeDecodeError):
                break
            if not isinstance(obj, dict):
                break
            op = obj.get("op")
            key = obj.get("key")
            if op == "put" and "value" in obj:
                state[key] = obj["value"]
            elif op == "delete":
                state.pop(key, None)
        return {key: state[key] for key in sorted(state)}

    def repair_tail(self):
        """Strip a truncated final line iff the rest of the chain is clean."""
        raw = self._read_bytes()
        if not raw:
            return {"repaired": False, "removed": 0, "refused": False}
        verdict = self.verify()
        if verdict["ok"]:
            return {"repaired": False, "removed": 0, "refused": False}
        if raw.endswith(b"\n"):
            return {"repaired": False, "removed": 0, "refused": True}
        parts = raw.split(b"\n")
        last_index = len(parts) - 1
        if verdict["first_bad_index"] != last_index:
            return {"repaired": False, "removed": 0, "refused": True}
        kept = parts[:-1]
        new_raw = b"\n".join(kept) + (b"\n" if kept else b"")
        self._write_atomic(new_raw)
        if self.verify()["ok"]:
            return {"repaired": True, "removed": 1, "refused": False}
        return {"repaired": False, "removed": 0, "refused": True}


# -- module-level functional API ------------------------------------------
# ``ledger.py`` exposes ``Ledger``, ``ConflictError``, ``append``,
# ``verify``, ``snapshot``, and ``apply_batch`` as callables at module scope
# (the repository-layout contract of R-13). These thin wrappers open a
# ``Ledger`` at the supplied path and delegate to the corresponding method.


def append(path, op):
    """Append one mutation ``(op, key, [value], rid, ts)`` to ``path``.

    Returns the committed line dict (or the previously committed line for an
    idempotent replay)."""
    return Ledger(path).append(op)


def verify(path):
    """Verify the hash chain of the ledger at ``path`` from disk.

    Returns ``{"ok": bool, "first_bad_index": int | None}``."""
    return Ledger(path).verify()


def snapshot(path):
    """Return the deterministic, NFC-sorted snapshot dict of ``path``."""
    return Ledger(path).snapshot()


def apply_batch(path, ops):
    """Atomically commit ``ops`` to the ledger at ``path``.

    Returns the number of lines appended."""
    return Ledger(path).apply_batch(ops)

